test('mergeCustomers removes fromId and keeps intoId', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-003');

  assert.equal(r.ok, true);
  assert(!r.value.customers.find(c => c.id === 'C-001'));
  assert(r.value.customers.find(c => c.id === 'C-003'));
});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-003');

  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-003');
  assert.equal(r.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers rejects same customer', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-001');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects normalized same customer', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'c-001', 'C-001');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects unknown fromId', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-999', 'C-003');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-999');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers does not mutate input arrays', () => {
  const customers = listCustomers();
  const originalLength = customers.length;
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const invoices = [inv1];

  mergeCustomers(customers, invoices, 'C-001', 'C-003');

  assert.equal(customers.length, originalLength);
  assert(customers.find(c => c.id === 'C-001'));
});

test('mergeCustomers with multiple invoices from fromId', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0002']).value;

  const invoices = [issued1, issued2, issued3];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-003');

  assert.equal(r.ok, true);
  const fromIdInvoices = r.value.invoices.filter(inv => inv.customerId === 'C-001');
  assert.equal(fromIdInvoices.length, 0);
  const toIdInvoices = r.value.invoices.filter(inv => inv.customerId === 'C-003');
  assert.equal(toIdInvoices.length, 3);
});

test('mergeCustomers with case-insensitive IDs', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], ' c-001 ', 'C-003');

  assert.equal(r.ok, true);
  assert(!r.value.customers.find(c => c.id === 'C-001'));
});

